// dns.Msg. It is used to pass structured DNS data through the proxy pipeline
// instead of raw protocol messages.
type MsgDetails struct {
	// QName is the canonical (lower-cased) query name of the first question,
	// including the trailing dot.
	QName string
	// QTypes is the list of question types in the message.
	QTypes []uint16
	// Response is true when the message is a DNS response.
	Response bool
	// ResponseIPs are the A/AAAA answer IPs. Only populated for responses.
	ResponseIPs []netip.Addr
	// CNAMEs are the CNAME targets in the answer chain. Only populated for
	// responses.
	CNAMEs []string
	// AnswerTypes are the RR types of the answer section. Only populated for
	// responses.
	AnswerTypes []uint16
	// TTL is the lowest applicable TTL of the answer section. Only populated
	// for responses.
	TTL uint32
	// RCode is the DNS response code.
	RCode int
}

// ExtractRequestMsgDetails extracts structured details from a DNS request
// message. It returns an error if the message has no question section.
//
// For valid requests it returns a MsgDetails with QName and QTypes populated
// and Response set to false. Response-specific fields (ResponseIPs, CNAMEs,
// AnswerTypes) are always nil and TTL is always 0, even if the message carries
// a (possibly spoofed) answer section.
func ExtractRequestMsgDetails(msg *dns.Msg) (*MsgDetails, error) {
	if len(msg.Question) == 0 {
		return nil, errors.New("Invalid DNS message")
	}

	qTypes := make([]uint16, 0, len(msg.Question))
	for _, q := range msg.Question {
		qTypes = append(qTypes, q.Qtype)
	}

	return &MsgDetails{
		QName:    strings.ToLower(string(msg.Question[0].Name)),
		QTypes:   qTypes,
		Response: false,
		RCode:    msg.Rcode,
	}, nil
}

// ExtractResponseMsgDetails extracts a canonical query name, any IPs in a
// response, the lowest applicable TTL, rcode, answer rr types and question
// types. When a CNAME is returned the chain is collapsed down, keeping the
// lowest TTL, and CNAME targets are returned.
//
// It returns an error if the message has no question section.
func ExtractResponseMsgDetails(msg *dns.Msg) (*MsgDetails, error) {
	if len(msg.Question) == 0 {
		return nil, errors.New("Invalid DNS message")
	}

	details := &MsgDetails{
		QName:    strings.ToLower(string(msg.Question[0].Name)),
		Response: msg.Response,
		RCode:    msg.Rcode,
	}

	TTL := uint32(math.MaxUint32) // a TTL must exist in the RRs

	details.AnswerTypes = make([]uint16, 0, len(msg.Answer))
	for _, ans := range msg.Answer {
		// Handle A, AAAA and CNAME records by accumulating IPs and lowest TTL
		switch ans := ans.(type) {
		case *dns.A:
			ip, ok := netipx.FromStdIP(ans.A)
			if !ok {
				return nil, errors.New("invalid IP in A record")
			}
			details.ResponseIPs = append(details.ResponseIPs, ip)
			if TTL > ans.Hdr.Ttl {
				TTL = ans.Hdr.Ttl
			}
		case *dns.AAAA:
			ip, ok := netipx.FromStdIP(ans.AAAA)
			if !ok {
				return nil, errors.New("invalid IP in AAAA record")
			}
			details.ResponseIPs = append(details.ResponseIPs, ip)
			if TTL > ans.Hdr.Ttl {
				TTL = ans.Hdr.Ttl
			}
		case *dns.CNAME:
			// We still track the TTL because the lowest TTL in the chain
			// determines the valid caching time for the whole response.
			if TTL > ans.Hdr.Ttl {
				TTL = ans.Hdr.Ttl
			}
			details.CNAMEs = append(details.CNAMEs, ans.Target)
		}
		details.AnswerTypes = append(details.AnswerTypes, ans.Header().Rrtype)
	}
	details.TTL = TTL

	details.QTypes = make([]uint16, 0, len(msg.Question))
	for _, q := range msg.Question {
		details.QTypes = append(details.QTypes, q.Qtype)
	}

	return details, nil
